    stroke: #000;
    stroke-opacity: 0.2;
}
.axis text {
    font: 9px Verdana;
	text-anchor:end;
}
</style>
<body>

<script type="text/javascript">
var height = 500, 
    width = 500, 
	margin=30,
	data=[
		{name: "Ливерпуль", score: 54},
		{name: "Ман. Юнайтед", score: 62},
		{name: "Арсенал", score: 66},
		{name: "Челси", score: 70},
		{name: "Ман. Сити", score: 61},
	];

// функция для получения цветов
var color = d3.scale.category10();

// длина оси X= ширина контейнера svg - отступ слева и справа
var xAxisLength = width - 2 * margin;     

// длина оси Y = высота контейнера svg - отступ сверху и снизу
var yAxisLength = height - 2 * margin;

// функция интерполяции значений на ось X
var xScale = d3.scale.ordinal()
		.rangeRoundBands([0, xAxisLength + margin], .1)
		.domain(data.map(function(d) { return d.name; }));

// функция интерполяции значений на ось Y
var yScale = d3.scale.linear()
	.domain([	
			d3.min(data, function(d) { return d.score - 10; }),
			d3.max(data, function(d) { return d.score + 10; })
	]).range([yAxisLength, 0]);

var svg = d3.select("body").append("svg")
		.attr("class", "axis")
        .attr("width", width)
        .attr("height", height);

// создаем ось X   
var xAxis = d3.svg.axis()
            .scale(xScale)
            .orient("bottom");
// создаем ось Y			 
var yAxis = d3.svg.axis()
             .scale(yScale)
             .orient("left");

 // отрисовка оси Х             
svg.append("g")       
     .attr("class", "x-axis")
     .attr("transform",
         "translate(" + margin + "," + (height - margin) + ")")
    .call(xAxis);

 // отрисовка оси Y	
svg.append("g")       
    .attr("class", "y-axis")
    .attr("transform",
            "translate(" + margin + "," + margin + ")")
    .call(yAxis);

// рисуем горизонтальные линии 
d3.selectAll("g.y-axis g.tick")
    .append("line")
    .classed("grid-line", true)
    .attr("x1", 0)
    .attr("y1", 0)
    .attr("x2", xAxisLength)
    .attr("y2", 0);

// создаем элемент g с набором столбиков
svg.append("g")
    .attr("transform",  // сдвиг оси вправо
         "translate(" + margin + ", 0)")
	.selectAll(".bar")
	.data(data)
	.enter().append("rect")
	.attr("class", "bar")
	.attr("x", function(d) { return xScale(d.name); })
	.attr("width", xScale.rangeBand())
	.attr("y", function(d) { return yScale(d.score); })
	.attr("height", function(d) { return height - yScale(d.score) - 30; })
	.attr("fill", function(d) { return color(d.name); });

</script>
</body>
</html>
```

![гистограммы в d3.js](/uploads/course-lectures/a837217a6ed9a2f3d54d29e7d3c0713cdf9b7e85.png)

Так как по горизонтали располагаются не какие-то количественные показатели, а названия команд, выполняющие роль подписей к столбикам, то надо применить функцию d3.scale.ordinal() :

```javascript
var xScale = d3.scale.ordinal()
		.rangeRoundBands([0, xAxisLength + margin], .1)
		.domain(data.map(function(d) { return d.name; }));
```

Функция `rangeRoundBands()` принимает отрезок, на котором будут располагаться названия команд (`[0, xAxisLength + margin]`), а также коэффициент масштабирования столбиков - `0.1`.

А функция `domain()` получает данные, с которыми будет сопоставляться вышеопределенный отрезок [0, xAxisLength + margin].

Для задания цвета каждого столбика здесь определена функция `var color = d3.scale.category10();`, которая возвращает один из 10 цветов по порядку.

Как и при линейном графике, здесь также создаются координатные оси, но без вертикальных линий сетки, так как значения по оси Х нам не нужны. И ключевой момент заключается в создании самих столбиков гистограммы:

```javascript
svg.append("g")
    .attr("transform",  // сдвиг оси вниз и вправо
         "translate(" + margin + ", 0)")
	.selectAll(".bar")
	.data(data)
	.enter().append("rect")
	.attr("class", "bar")
	.attr("x", function(d) { return xScale(d.name); })
	.attr("width", xScale.rangeBand())
	.attr("y", function(d) { return yScale(d.score) + margin; })
    .attr("height", function(d) { return yAxisLength - yScale(d.score); })
	.attr("fill", function(d) { return color(d.name); });
```

Круговые диаграммы (pie charts) представляют отображение данных в виде отдельных секторов в пределах окружности. В D3.js каждый сектор представлен объектом арки, которая генерируется с помощью метода d3.svg.arc() . Например, у нас есть данные по доли браузеров и нам надо эти данные отобразить:

```xml
<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<script src="http://d3js.org/d3.v3.min.js"> </script>
<style>
body {
	font: 13px Verdana;
}
.arc path {
	stroke: #000;
}
</style>
<body>

<script type="text/javascript">
var height = 500, 
    width = 500, 
	margin=30,
	data=[
		{browser: "Google Chrome", rate: 42.52},
		{browser: "Firefox", rate: 16.23},
		{browser: "Opera", rate: 12.6},
		{browser: "Yandex Browser", rate: 9.12},
		{browser: "Internet Explorer", rate: 10.56},
		{browser: "Другие", rate: 8.97}
	];

// функция для получения цветов
var color = d3.scale.category10();

// задаем радиус
var radius = Math.min(width - 2*margin, height- 2*margin) / 2;

// создаем элемент арки с радиусом
var arc = d3.svg.arc()
	.outerRadius(radius)
	.innerRadius(0);

var pie = d3.layout.pie()
	.sort(null)
	.value(function(d) { return d.rate; });

var svg = d3.select("body").append("svg")
		.attr("class", "axis")
        .attr("width", width)
        .attr("height", height)
		.append("g")
		.attr("transform", 
			"translate(" +(width / 2) + "," + (height / 2 ) + ")");
var g = svg.selectAll(".arc")
.data(pie(data))
.enter().append("g")
.attr("class", "arc");	

g.append("path")
.attr("d", arc)
.style("fill", function(d) { return color(d.data.browser); });

g.append("text")
	.attr("transform", function(d) {
		return "translate(" + arc.centroid(d) + ")"; })
	.style("text-anchor", "middle")
	.text(function(d) { return d.data.browser; });

</script>
</body>
</html>
```

![круговая диаграмма в d3.js](/uploads/course-lectures/e46a7216632cbd6de6da73c6e868c1eda7a7fff4.png)

Для создания каждой отдельной арки необходимо два радиуса: внутренний и внешний.

![радиус круговой диаграммы](/uploads/course-lectures/faab4d504e9918e9d7d42cce3d44f487851aff5a.png)

Внешний радиус будет равен половине ширины или высоты контейнера svg минус отступы. Внутренний радиус равен 0, поэтому дуга фактически будет представлять целый сектор, который отсекается от центра окружности:

```javascript
var radius = Math.min(width - 2*margin, height- 2*margin) / 2;

var arc = d3.svg.arc()
	.outerRadius(radius)
	.innerRadius(0);
```

Для автоматического создания круговой диаграммы или "пирога" (pie) в D3.js предусмотрена функция d3.layout.pie() :

```javascript
var pie = d3.layout.pie()
	.sort(null)
	.value(function(d) { return d.rate; });
```

В соответствии со значением rate у каждого объекта в массиве data ему будет определяться свой сектор.

Далее надо собственно нарисовать дуги, представляющие сектора:

```javascript
var g = svg.selectAll(".arc")
	.data(pie(data))
	.enter().append("g")
	.attr("class", "arc");	

g.append("path")
	.attr("d", arc)
	.style("fill", function(d) { return color(d.data.browser); });
g.append("text")
	.attr("transform", function(d) {
		return "translate(" + arc.centroid(d) + ")"; })
	.style("text-anchor", "middle")
	.text(function(d) { return d.data.browser; });
```

Но в качестве данных здесь будет использоваться не массив data, а результат вышеопределенной функции pie над этим массивом. Поэтому при определении текста на секторе используется не `d.browser`, а `d.data.browser`.

Чтобы определить место для метки текста, здесь применяется функция arc.centroid() , которая вычисляет центральную точку между внутренним и внешним радиусом.

В прошлой теме при построении диаграммы у нас был один минус: надписи секторах не всегда могут уместиться, особенно когда сектора занимают считанные проценты от окружности. В этом плане для добавления текстовых меток более эффективно использование легенды, которая соотносит используемые на диаграмме цвета с текстовыми метками секторов. Добавим на диаграмму из прошлой темы легенду:

```xml
<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<script src="http://d3js.org/d3.v3.min.js"> </script>
<style>
body {
	font: 13px Verdana;
}
.arc path {
	stroke: #000;
}
</style>
<body>

<script type="text/javascript">
var height = 500, 
    width = 500, 
	margin=30,
	data=[
		{browser: "Google Chrome", rate: 42.52},
		{browser: "Firefox", rate: 16.23},
		{browser: "Opera", rate: 12.6},
		{browser: "Internet Explorer", rate: 10.56},
		{browser: "Yandex Browser", rate: 9.12},
		{browser: "Другие", rate: 8.97},
	];

// функция для получения цветов
var color = d3.scale.category10();

// задаем радиус
var radius = Math.min(width - 2*margin, height- 2*margin) / 2.5;

// создаем элемент арки с радиусом
var arc = d3.svg.arc()
	.outerRadius(radius)
	.innerRadius(0);

var pie = d3.layout.pie()
	.sort(null)
	.value(function(d) { return d.rate; });

var svg = d3.select("body").append("svg")
		.attr("class", "axis")
        .attr("width", width)
        .attr("height", height)
		.append("g")
		.attr("transform", 
			"translate(" +(width / 2 )+ "," + (height / 2 ) + ")");
var g = svg.selectAll(".arc")
.data(pie(data))
.enter().append("g")
.attr("class", "arc");	

g.append("path")
.attr("d", arc)
.style("fill", function(d) { return color(d.data.browser); });

g.append("text")
	.attr("transform", function(d) {
		return "translate(" + arc.centroid(d) + ")"; })
	.style("text-anchor", "middle")
	.text(function(d) { return d.data.rate + "%"; });

var legendTable = d3.select("svg").append("g")
	.attr("transform", "translate(0, "+margin+")")
	.attr("class", "legendTable");

var legend = legendTable.selectAll(".legend")
	.data(pie(data))
	.enter().append("g")
	.attr("class", "legend")
	.attr("transform", function(d, i) {
		return "translate(0, " + i * 20 + ")"; 
	});

legend.append("rect")
	.attr("x", width - 10)
	.attr("y", 4)
	.attr("width", 10)
	.attr("height", 10)
	.style("fill", function(d) { return color(d.data.browser); });

legend.append("text")
	.attr("x", width - 14)
	.attr("y", 9)
	.attr("dy", ".35em")
	.style("text-anchor", "end")
	.text(function(d) { return d.data.browser; });

</script>
</body>
</html>
```

![легенда диаграммы в d3.js](/uploads/course-lectures/d084ef458a4a02f18e694c38569fefc2b2db6f54.png)

Главная проблема при создании легенды заключается лишь в подборе оптимальных координат для ее размещения. Само создание легенды представляет генерацию прямоугольников, окрашенных в цвета соответствующих секторов, и текстовых меток к ним.
